-- Migration 26: memory studio (music, text, stickers, mentions, drawing, filters, close friends), reel studio settings,
-- and song lengths for the music library. Additive and re-runnable; no existing row is rewritten.
--
-- 1. close_friends: each member's own list. Only the owner reads or changes it; the people on it are never told.
-- 2. memories gain: a song (from the VYBE library, or the member's own file in their media folder) with the moment of the
--    song it starts at; overlays (text, stickers, @mentions and drawing, as small JSON drawn on top by the viewer); a
--    filter; and a third audience, 'close_friends'. can_view_memory learns the new audience; a member's own song file is
--    readable exactly when the memory is.
-- 3. posts.reel_edit: how a reel plays (filter, speed, trim, original/music volume, where the song starts). Presentation
--    only: small JSON object, never parsed by the server.
-- 4. music_tracks.duration_ms (set by admins when they upload; the library shows it), returned by music_catalog. Trending
--    also counts songs used in memories.
--
-- Rollback: re-run can_view_memory, author_memories, music_catalog and media_select_visible from migrations 11/25; drop the
-- memories columns music_track_id, music_title, music_artist, music_path, music_start_ms, overlays, filter (after putting
-- back the visibility check with ('public', 'friends')); alter table public.posts drop column reel_edit; alter table
-- public.music_tracks drop column duration_ms; drop table public.close_friends.

-- ---------------------------------------------------------------- 1. close friends
create table if not exists public.close_friends (
  owner uuid not null references public.profiles(id) on delete cascade,
  friend uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (owner, friend),
  check (owner <> friend)
);
create index if not exists close_friends_friend_idx on public.close_friends (friend, owner);
alter table public.close_friends enable row level security;
drop policy if exists close_friends_read on public.close_friends;
create policy close_friends_read on public.close_friends for select to authenticated using (owner = (select auth.uid()));
drop policy if exists close_friends_ins on public.close_friends;
create policy close_friends_ins on public.close_friends for insert to authenticated
  with check (owner = (select auth.uid()) and not public.is_blocked(owner, friend));
drop policy if exists close_friends_del on public.close_friends;
create policy close_friends_del on public.close_friends for delete to authenticated using (owner = (select auth.uid()));
revoke all on public.close_friends from anon, authenticated;
grant select, insert, delete on public.close_friends to authenticated;

create or replace function public.trg_close_friends_limit() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (select count(*) from public.close_friends where owner = new.owner) >= 500 then raise exception 'Your close friends list is full (500 people).'; end if;
  return new;
end $$;
drop trigger if exists close_friends_limit on public.close_friends;
create trigger close_friends_limit before insert on public.close_friends for each row execute function public.trg_close_friends_limit();

-- ---------------------------------------------------------------- 2. memory studio
alter table public.memories add column if not exists music_track_id uuid references public.music_tracks(id) on delete set null;
alter table public.memories add column if not exists music_title text check (music_title is null or char_length(music_title) between 1 and 120);
alter table public.memories add column if not exists music_artist text check (music_artist is null or char_length(music_artist) <= 120);
alter table public.memories add column if not exists music_path text check (music_path is null or char_length(music_path) <= 200);
alter table public.memories add column if not exists music_start_ms integer not null default 0 check (music_start_ms between 0 and 3600000);
alter table public.memories add column if not exists overlays jsonb not null default '[]'::jsonb;
alter table public.memories add column if not exists filter text not null default 'none';
alter table public.memories drop constraint if exists memories_music_path_owner;
alter table public.memories add constraint memories_music_path_owner check (music_path is null or music_path like author::text || '/%');
alter table public.memories drop constraint if exists memories_music_named;
alter table public.memories add constraint memories_music_named check ((music_track_id is null and music_path is null) or music_title is not null);
alter table public.memories drop constraint if exists memories_overlays_shape;
alter table public.memories add constraint memories_overlays_shape check (jsonb_typeof(overlays) = 'array' and jsonb_array_length(overlays) <= 60 and pg_column_size(overlays) <= 48000);
alter table public.memories drop constraint if exists memories_filter_known;
alter table public.memories add constraint memories_filter_known check (filter in ('none', 'vivid', 'warm', 'cool', 'mono', 'fade', 'noir', 'dream', 'film'));
alter table public.memories drop constraint if exists memories_visibility_check;
alter table public.memories add constraint memories_visibility_check check (visibility in ('public', 'friends', 'close_friends'));
create index if not exists memories_music_path_idx on public.memories (music_path) where music_path is not null;
create index if not exists memories_music_idx on public.memories (music_track_id, created_at desc) where music_track_id is not null;
grant insert (music_track_id, music_title, music_artist, music_path, music_start_ms, overlays, filter) on public.memories to authenticated;

create or replace function public.can_view_memory(m public.memories) returns boolean
language sql stable security definer set search_path = '' as $$
  select m.author = auth.uid() or (
    not public.is_blocked(auth.uid(), m.author)
    and (m.expires_at > now() or m.highlight)
    and (m.visibility = 'public'
         or (m.visibility = 'friends' and public.are_friends(auth.uid(), m.author))
         or (m.visibility = 'close_friends' and exists (select 1 from public.close_friends cf where cf.owner = m.author and cf.friend = auth.uid())))
  );
$$;

-- Migration 11's reader, plus the studio fields and whether the viewer is on the author's close friends list (for the badge).
create or replace function public.author_memories(p_author uuid, p_highlights boolean default false) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare me uuid := auth.uid(); r jsonb;
begin
  if me is null then raise exception 'Sign in' using errcode = '28000'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', m.id, 'kind', m.kind, 'media_path', m.media_path, 'text_body', m.text_body, 'bg', m.bg, 'created_at', m.created_at, 'expires_at', m.expires_at,
    'visibility', m.visibility, 'highlight', m.highlight, 'highlight_title', m.highlight_title,
    'music_track_id', m.music_track_id, 'music_title', m.music_title, 'music_artist', m.music_artist, 'music_path', m.music_path, 'music_start_ms', m.music_start_ms,
    'music_preview_path', (select t.preview_path from public.music_tracks t where t.id = m.music_track_id and t.active),
    'music_artwork_path', (select t.artwork_path from public.music_tracks t where t.id = m.music_track_id and t.active),
    'overlays', m.overlays, 'filter', m.filter,
    'mine_reaction', (select emoji from public.memory_reactions x where x.memory_id = m.id and x.user_id = me),
    'seen', exists (select 1 from public.memory_views v where v.memory_id = m.id and v.viewer = me),
    'views', case when m.author = me then (select count(*) from public.memory_views v where v.memory_id = m.id) end,
    'reactions', case when m.author = me then (select count(*) from public.memory_reactions x where x.memory_id = m.id) end,
    'replies', case when m.author = me then (select count(*) from public.memory_replies y where y.memory_id = m.id) end
  ) order by m.created_at), '[]'::jsonb) into r
  from public.memories m
  where m.author = p_author and public.can_view_memory(m)
    and ((p_highlights and m.highlight) or (not p_highlights and m.expires_at > now()));
  return r;
end $$;

-- ---------------------------------------------------------------- 3. reel studio settings
alter table public.posts add column if not exists reel_edit jsonb;
alter table public.posts drop constraint if exists posts_reel_edit_shape;
alter table public.posts add constraint posts_reel_edit_shape check (reel_edit is null or (jsonb_typeof(reel_edit) = 'object' and pg_column_size(reel_edit) <= 2000));

-- ---------------------------------------------------------------- 4. song lengths
alter table public.music_tracks add column if not exists duration_ms integer check (duration_ms is null or duration_ms between 1000 and 3600000);

create or replace function public.music_catalog(p_tab text default 'foryou', p_q text default null, p_limit integer default 40) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare me uuid := auth.uid(); q text := nullif(btrim(replace(replace(coalesce(p_q, ''), '%', ''), '_', '')), ''); r jsonb;
begin
  if me is null then raise exception 'Sign in' using errcode = '28000'; end if;
  select coalesce(jsonb_agg(x.j order by x.rank1 desc, x.rank2 desc, x.created_at desc), '[]'::jsonb) into r from (
    select jsonb_build_object('id', t.id, 'title', t.title, 'artist', t.artist, 'artwork_path', t.artwork_path, 'preview_path', t.preview_path, 'external_url', t.external_url,
             'duration_ms', t.duration_ms, 'genre', t.genre,
             'saved', exists (select 1 from public.saved_tracks s where s.user_id = me and s.track_id = t.id)) as j,
           case p_tab when 'trending' then (select count(*) from public.posts p where p.music_track_id = t.id and p.created_at > now() - interval '14 days')
                                           + (select count(*) from public.memories m where m.music_track_id = t.id and m.created_at > now() - interval '14 days')
                      else (case when exists (select 1 from public.follows f join public.organizations o on o.id = f.target_id and f.target_type = 'organization' where f.follower = me and lower(o.name) = lower(t.artist)) then 1 else 0 end) end as rank1,
           0 as rank2, t.created_at
    from public.music_tracks t
    where t.active and (q is null or t.title ilike '%' || q || '%' or t.artist ilike '%' || q || '%')
      and (p_tab <> 'saved' or exists (select 1 from public.saved_tracks s where s.user_id = me and s.track_id = t.id))
    limit least(greatest(p_limit, 1), 100)
  ) x;
  return r;
end $$;

-- ---------------------------------------------------------------- media read rule: a memory's own song file
drop policy if exists media_select_visible on storage.objects;
create policy media_select_visible on storage.objects for select to authenticated
  using (
    bucket_id = 'media' and (
      (storage.foldername(objects.name))[1] = (select auth.uid())::text
      or exists (select 1 from public.posts p where p.media_path = objects.name or p.music_path = objects.name)
      or exists (select 1 from public.post_media pm where pm.path = objects.name or pm.poster_path = objects.name or pm.display_path = objects.name)
      or exists (select 1 from public.comments c where c.audio_path = objects.name or c.video_path = objects.name)
      or exists (select 1 from public.profiles pr where pr.avatar_path = objects.name or pr.cover_path = objects.name)
      or exists (select 1 from public.events e where e.cover_path = objects.name or e.hero_video_path = objects.name)
      or exists (select 1 from public.event_lineup l where l.image_path = objects.name)
      or exists (select 1 from public.communities c where c.cover_path = objects.name)
      or exists (select 1 from public.memories m where m.media_path = objects.name or m.music_path = objects.name)
      or exists (select 1 from public.memory_replies r where r.audio_path = objects.name)
      or exists (select 1 from public.messages m where m.media_path = objects.name or m.audio_path = objects.name)
      or exists (select 1 from public.organizations o where o.avatar_path = objects.name or o.cover_path = objects.name)
      or exists (select 1 from public.media_assets a where a.organization_id is not null and (a.path = objects.name or a.thumb_path = objects.name))
    )
  );

commit;

select item, ok from (values
  ('Close Friends list (owner only)', to_regclass('public.close_friends') is not null and has_table_privilege('authenticated', 'public.close_friends', 'insert') and not has_table_privilege('anon', 'public.close_friends', 'select')),
  ('memory song, overlays and effect', (select count(*) from information_schema.columns where table_name = 'memories' and column_name in ('music_track_id', 'music_title', 'music_path', 'music_start_ms', 'overlays', 'filter')) = 6),
  ('Close Friends audience understood by the visibility rule', (select prosrc from pg_proc where proname = 'can_view_memory') like '%close_friends%'),
  ('memory songs readable with their memory', (select pg_get_expr(polqual, polrelid) from pg_policy where polname = 'media_select_visible') like '%m.music_path%'),
  ('reel settings and song lengths', exists (select 1 from information_schema.columns where table_name = 'posts' and column_name = 'reel_edit') and exists (select 1 from information_schema.columns where table_name = 'music_tracks' and column_name = 'duration_ms'))
) as v(item, ok);
